function parseCreateUser(input) {
  if (!input || typeof input !== "object") throw new ValidationError("body must be an object");
  if (typeof input.email !== "string") throw new ValidationError("email is required");
  return { email: input.email.trim().toLowerCase() };
}

function toPublicUser(row) {
  return { id: row.id, email: row.email, displayName: row.display_name, createdAt: row.created_at.toISOString() };
}

