async function getUser(id) {
  const key = `user:${id}`;
  const cached = await cache.get(key);
  if (cached) return JSON.parse(cached);
  const user = await db.users.findById(id);
  if (user) await cache.set(key, JSON.stringify(user), { ttl: 60 });
  return user;
}
